// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<h2 id=\"managing-http-requests-in-the-angular-signals-era\" data-line=\"0\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#managing-http-requests-in-the-angular-signals-era\" aria-hidden=\"true\"></a> Managing HTTP Requests in the Angular Signals Era</h2>\n<p data-line=\"2\" class=\"code-line\">Signals, introduced in Angular 16 and later, add a new option for state management in Angular. This article explains how to manage HTTP requests efficiently with Signals, with practical examples.</p>\n<h2 id=\"http-request-basics\" data-line=\"4\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#http-request-basics\" aria-hidden=\"true\"></a> HTTP request basics</h2>\n<p data-line=\"6\" class=\"code-line\">First, here is a basic HTTP request with Signals. If you are not doing side-effectful work, you can also bind directly in the template and manage display with the <code>async</code> pipe. In that case, the request runs when the template renders.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"8\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template:</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `@if (!isLoading()) { @for (item of users(); track item.id) { ... } }`</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserComponent</span><span style=\"color:#F97583\"> implements</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#F97583\"> readonly</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> users</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">[]&gt;([]);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> isLoading</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">boolean</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.isLoading.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">[]&gt;(</span><span style=\"color:#9ECBFF\">'/api/users'</span><span style=\"color:#E1E4E8\">).</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      next</span><span style=\"color:#E1E4E8\">: (</span><span style=\"color:#FFAB70\">data</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        this</span><span style=\"color:#E1E4E8\">.isLoading.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        this</span><span style=\"color:#E1E4E8\">.users.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(data);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"30\" class=\"code-line\">Note that you cannot re-request for data updates with this alone. If you need a refetch, you have to build your own <code>Observable</code> and call <code>next</code>, which takes a bit of work.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"32\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> refreshTrigger</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Subject</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">void</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  data$</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Observable</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">any</span><span style=\"color:#E1E4E8\">&gt; </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.refreshTrigger.</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    startWith</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    switchMap</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/api/users'</span><span style=\"color:#E1E4E8\">))</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"44\" class=\"code-line\">If you use the value inside the class, you need to <code>subscribe</code> to <code>data$</code> and <code>unsubscribe</code> via Angular lifecycle hooks. That is the familiar pattern.</p>\n<h2 id=\"implementation-with-the-resource-api\" data-line=\"47\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#implementation-with-the-resource-api\" aria-hidden=\"true\"></a> Implementation with the Resource API</h2>\n<p data-line=\"49\" class=\"code-line\">The Resource API introduced in Angular 17 lets you manage HTTP requests more declaratively. It still fires when the template renders, but the <code>resource</code> API includes a <code>reload</code> method, so refetching is easy.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"51\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `@if (!users.isLoading()) { @for (item of users.value(); track item.id) { ... } }`</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  users</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    loader</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">[]&gt;(</span><span style=\"color:#9ECBFF\">'/api/users'</span><span style=\"color:#E1E4E8\">))</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  })</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // This alone triggers a new request; it can also be done from the template</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  reload</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.users.</span><span style=\"color:#B392F0\">reload</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"68\" class=\"code-line\">You can also use the <code>request</code> property to refetch whenever the Signals passed to <code>request</code> change.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"70\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userId</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  users</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    request</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> ({userId: </span><span style=\"color:#B392F0\">userId</span><span style=\"color:#E1E4E8\">()}),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    loader</span><span style=\"color:#E1E4E8\">: ({</span><span style=\"color:#FFAB70\">request</span><span style=\"color:#E1E4E8\">}) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">[]&gt;(</span><span style=\"color:#9ECBFF\">'/api/users/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> request.userId))</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  })</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"82\" class=\"code-line\">Compared with managing everything through <code>Observable</code>, this is much simpler. Because behavior is driven by Signal state rather than lifecycle or user actions, it is easier to write pure logic and improve testability.</p>\n<h3 id=\"what-about-httpresource%3F\" data-line=\"84\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#what-about-httpresource%3F\" aria-hidden=\"true\"></a> What about httpResource?</h3>\n<p data-line=\"86\" class=\"code-line\">Above, I convert <code>HttpClient</code> to a Promise and pair it with the <code>resource</code> API. There is also an experimental <code>httpResource</code> API that combines the two.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"88\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userId</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  users</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/api/users/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">userId</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"96\" class=\"code-line\">Internally it is an <code>HttpRequest</code>, so <code>Interceptor</code> still works, which is great. In a real project, though, you may hit a few pain points.<br>\nYou may need to transform the response, and if several components share the data, you probably want a Service. For example:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"99\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Service</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserService</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  resourceUsers</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">userId</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> WritableSignal</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/api/users/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">userId</span><span style=\"color:#E1E4E8\">(), {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        map</span><span style=\"color:#E1E4E8\">: (</span><span style=\"color:#FFAB70\">data</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">        // Perform the necessary complex processing here</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#E1E4E8\"> data;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"113\" class=\"code-line\">However, <code>resourceUsers</code> is not a Promise, so you cannot resolve it with <code>await this.userService.resourceUsers(this.userId())</code>. If another component needs this value from a click handler, you must preload it as a property first. Alternatively, wrap it in a Promise and poll with <code>setInterval</code> until a value appears, or convert with <code>toObservable</code> and then to a Promise. Neither feels practical.</p>\n<p data-line=\"115\" class=\"code-line\"><a href=\"https://github.com/angular/angular/issues/58917\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/angular/angular/issues/58917</a><a href=\"https://github.com/angular/angular/issues/58917\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/angular/angular/issues/58917</a></p>\n<p data-line=\"117\" class=\"code-line\">Because it is still experimental, Angular may add a fix later, but for overall project structure I would adopt <code>httpResouce</code> carefully today.</p>\n<h2 id=\"practical-http-requests\" data-line=\"120\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#practical-http-requests\" aria-hidden=\"true\"></a> Practical HTTP requests</h2>\n<p data-line=\"122\" class=\"code-line\">Fetching data to render a component is practical enough, but let us go one step further.</p>\n<h2 id=\"infinite-scroll-implementation\" data-line=\"124\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#infinite-scroll-implementation\" aria-hidden=\"true\"></a> Infinite scroll implementation</h2>\n<p data-line=\"126\" class=\"code-line\">Consider infinite scroll. The Signal that drives <code>request</code> should represent the scroll page—the page number to fetch (or, depending on implementation, the last item id). Use a <code>page</code> WritableSignal for that. When showing page 0, you need requests for:</p>\n<ul data-line=\"128\" class=\"code-line\">\n<li data-line=\"128\" class=\"code-line\">Initial display</li>\n<li data-line=\"129\" class=\"code-line\">Refresh</li>\n</ul>\n<p data-line=\"131\" class=\"code-line\">In those cases, you should show only that page's items. When scrolling, you need to append fetched items to what is already shown.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"133\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> InfiniteScrollComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  page</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  items</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Item</span><span style=\"color:#E1E4E8\">[]&gt;([]);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    effect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      const</span><span style=\"color:#79B8FF\"> page</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">page</span><span style=\"color:#E1E4E8\">(); </span><span style=\"color:#a0aab5\">// React to this value</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      const</span><span style=\"color:#79B8FF\"> data</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/api/users/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> page));</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.items.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">item</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        if</span><span style=\"color:#E1E4E8\"> (page </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">            return</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">data]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        } </span><span style=\"color:#F97583\">else</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">            return</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">item, </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">data]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      })</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    })</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Request the next page</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loadMore</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">page</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> page </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  refresh</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"161\" class=\"code-line\">Before, I wrote handlers for user events. With Signals, I write logic against state changes, which stays much simpler.</p>\n<h2 id=\"summary\" data-line=\"164\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"166\" class=\"code-line\">Signals make HTTP request state management more intuitive and improve readability. Benefits include:</p>\n<ul data-line=\"168\" class=\"code-line\">\n<li data-line=\"168\" class=\"code-line\">Easier reactive state management</li>\n<li data-line=\"169\" class=\"code-line\">Clearer component state</li>\n<li data-line=\"170\" class=\"code-line\">Simpler async state handling</li>\n<li data-line=\"171\" class=\"code-line\">Easier performance tuning</li>\n</ul>\n<p data-line=\"173\" class=\"code-line\">Signals are a newer Angular feature and should see more use over time. For HTTP requests, Signals help you write more maintainable code.</p>\n<p data-line=\"175\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"managing-http-requests-in-the-angular-signals-era","text":"Managing HTTP Requests in the Angular Signals Era","level":2},{"id":"http-request-basics","text":"HTTP request basics","level":2},{"id":"implementation-with-the-resource-api","text":"Implementation with the Resource API","level":2},{"id":"what-about-httpresource%3F","text":"What about httpResource?","level":3},{"id":"practical-http-requests","text":"Practical HTTP requests","level":2},{"id":"infinite-scroll-implementation","text":"Infinite scroll implementation","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
